109			dark, light := app.EffectiveThemeDark(), app.EffectiveThemeLight()
110			r = theme.ResolveAuto(bg, dark, light)
111			a.theme.pending = bg == theme.BackgroundUnknown
112			selected, other, otherBg := dark, light, theme.BackgroundLight
113			if bg == theme.BackgroundLight {
114				selected, other, otherBg = light, dark, theme.BackgroundDark
115			}
116			candidates = []candidate{
117				{selected, r.Warning},
118				{other, theme.ResolveAuto(otherBg, dark, light).Warning},
119			}
120		} else {
121			a.theme.gen++
122			a.theme.pending = false
123			r = theme.ResolveNamed(app.Theme)
124			candidates = []candidate{{app.Theme, r.Warning}}
125		}
126		a.theme.resolution = r
127		theme.ApplyTheme(r.Theme)
